// //napi: annotations only, and zz_napi.go, index.d.ts and index.js are generated by napi-go-gen.
package main

//go:generate go run github.com/napi-bindings/napi-go/cmd/napi-go-gen -name codegen

import (
	"context"
	"errors"
	"fmt"
	"math/big"
	"strings"
	"time"

	"github.com/napi-bindings/napi-go/napi"
)

// Version is the addon version.
//
//napi:export
const Version = "2.0.0"

// MaxItems bounds the size of a cart.
//
//napi:export MAX_ITEMS
const MaxItems = 3

// Add returns the sum of a and b.
//
//napi:export
func Add(a, b float64) float64 { return a + b }

// ParsePort checks that port is a valid TCP port.
// It throws a RangeError otherwise.
//
//napi:export
func ParsePort(port int) (uint16, error) {
	if port < 1 || port > 65535 {
		return 0, napi.RangeError("E_PORT", fmt.Sprintf("invalid port %d", port))
	}
	return uint16(port), nil
}

// Address is a postal address.
type Address struct {
	City string `json:"city"`
	// ZIP is the postal code.
	ZIP string `json:"zip,omitempty"`
}

// User is a registered user.
//
//napi:object
type User struct {
	ID    int64
	Name  string
	Email *string
	Tags  []string `napi:",omitempty"`
	Address
	Extra    map[string]any `napi:"extra,omitempty"`
	password string
}

// Greet returns a greeting for u.
//
//napi:export
func Greet(u User) string {
	return "hello " + u.Name + " from " + u.City + strings.Repeat("!", len(u.Tags)) + u.password
}

// FindUser loads a user in a goroutine; an empty name is an error.
//
//napi:export
func FindUser(ctx context.Context, name string) (*User, error) {
	if name == "" {
		return nil, errors.New("empty name")
	}
	if name == "nobody" {
		return nil, nil
	}
	return &User{ID: 1, Name: name, Address: Address{City: "Rome"}}, nil
}

// Touch waits for ms milliseconds in a goroutine.
//
//napi:export
func Touch(ctx context.Context, ms int) error {
	select {
	case <-time.After(time.Duration(ms) * time.Millisecond):
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// Checksum sums the bytes of data.
//
//napi:export
func Checksum(data []byte) uint32 {
	var s uint32
	for _, b := range data {
		s += uint32(b)
	}
	return s
}

// Describe names the kind of v.
//
//napi:export
func Describe(v napi.Either[string, float64], when time.Time, big *big.Int) string {
	kind := "number"
	if _, ok := v.A(); ok {
		kind = "string"
	}
	return fmt.Sprintf("%s %d %s", kind, when.UTC().Year(), big)
}

// Encode returns the UTF-8 bytes of s, repeated times times.
//
//napi:export
func Encode(s string, times int64) []byte { return []byte(strings.Repeat(s, int(times))) }

// Lookup returns table[key] for every key, or false for the missing ones.
//
//napi:export
func Lookup(table map[int]string, keys []int, opts struct{ Upper bool }) []napi.Either[string, bool] {
	out := make([]napi.Either[string, bool], len(keys))
	for i, k := range keys {
		v, ok := table[k]
		switch {
		case !ok:
			out[i] = napi.EitherB[string](false)
		case opts.Upper:
			out[i] = napi.EitherA[string, bool](strings.ToUpper(v))
		default:
			out[i] = napi.EitherA[string, bool](v)
		}
	}
	return out
}

// Count returns the number of JS arguments it was called with.
//
//napi:export
func Count(c napi.CallContext) int { return c.Len() }

// Callback calls fn with value and returns its result.
//
//napi:export
//napi:returns unknown
func Callback(fn napi.Function, value napi.Value) (napi.Value, error) { return fn.Call(napi.Value{}, value) }

// Point is a 2D point, converted as [x, y].
//
//napi:type [number, number]
type Point struct{ X, Y float64 }

func (p Point) ToJS(env napi.Env) (napi.Value, error) { return napi.ToValue(env, [2]float64{p.X, p.Y}) }

func (p *Point) FromJS(v napi.Value) error {
	xy, err := napi.FromValue[[2]float64](v)
	p.X, p.Y = xy[0], xy[1]
	return err
}

// Mirror reflects p across the origin.
//
//napi:export
func Mirror(p Point) Point { return Point{-p.X, -p.Y} }

// Item is a line of a cart.
type Item struct {
	Name  string
	Price float64
	Qty   int `napi:"quantity"`
}

// Cart is a shopping cart.
//
//napi:class
type Cart struct {
	owner string
	items []Item
}

// NewCart creates the cart of owner.
//
//napi:constructor
func NewCart(owner string) (*Cart, error) {
	if owner == "" {
		return nil, napi.TypeError("E_OWNER", "owner is required")
	}
	return &Cart{owner: owner}, nil
}

// Add appends an item and returns the cart, for chaining.
//
//napi:returns this
func (c *Cart) Add(item Item) (*Cart, error) {
	if len(c.items) >= MaxItems {
		return nil, napi.RangeError("E_FULL", "the cart is full")
	}
	c.items = append(c.items, item)
	return c, nil
}

// Total returns the total price.
func (c *Cart) Total() float64 {
	t := 0.0
	for _, it := range c.items {
		t += it.Price * float64(it.Qty)
	}
	return t
}

// Items returns a copy of the lines.
func (c *Cart) Items() []Item { return append([]Item(nil), c.items...) }

// Clear removes every line.
func (c *Cart) Clear() { c.items = nil }

// Owner is the name of the owner.
//
//napi:getter
func (c *Cart) Owner() string { return c.owner }

// SetOwner changes the owner.
//
//napi:setter
func (c *Cart) SetOwner(owner string) { c.owner = owner }

// Size is the number of lines.
//
//napi:getter size
func (c *Cart) Size() int { return len(c.items) }

// Merge moves the lines of other into the cart.
//
//napi:export mergeFrom
func (c *Cart) Merge(other *Cart) {
	if other != nil {
		c.items = append(c.items, other.items...)
		other.items = nil
	}
}

// Secret is not exported to JS.
//
//napi:skip
func (c *Cart) Secret() string { return "hidden" }

// Finalize runs when the JS instance is collected; it is never a JS method.
func (c *Cart) Finalize(napi.Env) {}

func (c *Cart) internal() int { return len(c.items) }

// CartOf creates a cart with one line.
//
//napi:export Cart.of
func CartOf(owner string, item Item) *Cart { return &Cart{owner: owner, items: []Item{item}} }

// CartCapacity is the capacity of every cart.
//
//napi:export Cart.CAPACITY
const CartCapacity = MaxItems

// Session is created by OpenSession only: it has no JS constructor.
//
//napi:class
type Session struct{ id int }

// ID returns the session number.
func (s *Session) ID() int { return s.id }

// OpenSession opens session id.
//
//napi:export
func OpenSession(id int) *Session { return &Session{id: id} }

func main() {}
